// The Report model: one generated report and where it went.
export interface Report {
  id: string;
  title: string;
  generatedAt: Date;
  /** Email addresses the report was delivered to; empty until delivery. */
  deliveredTo: string[];
}

import { createHash, randomBytes } from "crypto";
import bcrypt from "bcryptjs";
import { Router, type NextFunction, type Request, type Response } from "express";
import jwt from "jsonwebtoken";
import { z } from "zod";
import { config } from "../config";
import { userRepo } from "../db/repos/userRepo";
import { logger } from "../logger";
import { sendEmail } from "../notifications/email";
import { passwordResetEmail } from "../notifications/templates";
import type { AuthUser } from "../types";
import { addMinutes } from "../util/dates";
import { asyncHandler, HttpError } from "./errors";

declare global {
  // eslint-disable-next-line @typescript-eslint/no-namespace
  namespace Express {
    interface Request {
      user?: AuthUser;
    }
  }
}

const BCRYPT_ROUNDS = 12;

const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(1),
});

const resetRequestSchema = z.object({
  email: z.string().email(),
});

const resetConfirmSchema = z.object({
  token: z.string().min(32).max(128),
  password: z.string().min(10).max(200),
});

const sha256 = (value: string) => createHash("sha256").update(value).digest("hex");

export function issueToken(user: AuthUser): string {
  return jwt.sign({ sub: user.id, email: user.email }, config.auth.jwtSigningKey, {
    expiresIn: `${config.auth.tokenTtlMinutes}m`,
  });
}

export function requireAuth(req: Request, _res: Response, next: NextFunction): void {
  const [scheme, token] = (req.header("authorization") ?? "").split(" ");
  if (scheme !== "Bearer" || !token) {
    next(new HttpError(401, "authentication required"));
    return;
  }
  try {
    const payload = jwt.verify(token, config.auth.jwtSigningKey) as jwt.JwtPayload;
    req.user = { id: String(payload.sub), email: String(payload.email) };
    next();
  } catch {
    next(new HttpError(401, "invalid or expired token"));
  }
}

export function currentUser(req: Request): AuthUser {
  if (!req.user) throw new HttpError(401, "authentication required");
  return req.user;
}

export const authRouter = Router();

authRouter.post(
  "/login",
  asyncHandler(async (req, res) => {
    const { email, password } = loginSchema.parse(req.body);
    const user = await userRepo.findByEmail(email);
    const ok = user ? await bcrypt.compare(password, user.passwordHash) : false;
    if (!user || !ok) throw new HttpError(401, "invalid email or password");
    res.json({ token: issueToken(user), expiresInMinutes: config.auth.tokenTtlMinutes });
  }),
);

authRouter.post(
  "/password-reset",
  asyncHandler(async (req, res) => {
    const { email } = resetRequestSchema.parse(req.body);
    const user = await userRepo.findByEmail(email);
    if (user) {
      const token = randomBytes(32).toString("hex");
      const expiresAt = addMinutes(new Date(), config.auth.resetTokenTtlMinutes);
      // Only the hash is stored; the raw token exists in the email and nowhere else.
      await userRepo.createResetToken(user.id, sha256(token), expiresAt);
      await sendEmail(passwordResetEmail(user, token));
      logger.info({ userId: user.id }, "password reset requested");
    }
    // Same response whether or not the account exists.
    res.status(202).json({ ok: true });
  }),
);

authRouter.post(
  "/password-reset/confirm",
  asyncHandler(async (req, res) => {
    const { token, password } = resetConfirmSchema.parse(req.body);
    const userId = await userRepo.consumeResetToken(sha256(token));
    if (!userId) throw new HttpError(400, "reset link is invalid or has expired");
    await userRepo.setPassword(userId, await bcrypt.hash(password, BCRYPT_ROUNDS));
    logger.info({ userId }, "password reset completed");
    res.status(204).end();
  }),
);

import type { NextFunction, Request, RequestHandler, Response } from "express";
import { ZodError } from "zod";
import { pickLocale, t } from "../i18n";
import { isIngestError } from "../ingest/errors";
import { logger } from "../logger";

export class HttpError extends Error {
  constructor(
    readonly status: number,
    message: string,
    readonly details?: unknown,
  ) {
    super(message);
    this.name = "HttpError";
  }
}

export const badRequest = (message: string, details?: unknown) => new HttpError(400, message, details);
export const notFoundError = (what: string) => new HttpError(404, `${what} not found`);

type AsyncRoute = (req: Request, res: Response) => Promise<unknown>;

/** Express 4 does not forward rejected promises to error middleware, so wrap async handlers. */
export const asyncHandler =
  (fn: AsyncRoute): RequestHandler =>
  (req, res, next) => {
    fn(req, res).catch(next);
  };

export function notFound(_req: Request, res: Response): void {
  res.status(404).json({ error: "not found" });
}

// Express recognises error middleware by its four parameters, so keep `_next`.
export function errorHandler(err: unknown, req: Request, res: Response, _next: NextFunction): void {
  if (res.headersSent) {
    logger.warn({ err, requestId: res.locals.requestId }, "error after response started");
    res.end();
    return;
  }

  if (err instanceof HttpError) {
    res.status(err.status).json({ error: err.message, details: err.details });
    return;
  }

  if (err instanceof ZodError) {
    res.status(400).json({ error: "validation failed", details: err.flatten().fieldErrors });
    return;
  }

  if (isIngestError(err)) {
    // Upload content problems: translate for the caller and pass the row number through.
    const locale = pickLocale(req.header("accept-language"));
    res.status(422).json({
      error: t(err.key, err.params, locale),
      code: err.key,
      row: err.params.row ?? null,
    });
    return;
  }

  logger.error({ err, requestId: res.locals.requestId }, "unhandled error");
  res.status(500).json({ error: "internal error", requestId: res.locals.requestId });
}

import { Router } from "express";
import { db } from "../db/client";
import { queueDepth } from "../ingest/queue";
import { asyncHandler } from "./errors";

type CheckStatus = "ok" | "degraded" | "down";

/** Above this many runnable import jobs we report the queue as degraded. */
const QUEUE_DEGRADED_AT = 500;
const VERSION = process.env.npm_package_version ?? "dev";

export const healthRouter = Router();

// Liveness: the process is up and the event loop is responsive.
healthRouter.get("/live", (_req, res) => {
  res.json({ status: "ok" });
});

// Readiness: dependencies are reachable.
healthRouter.get(
  "/",
  asyncHandler(async (_req, res) => {
    const checks: Record<"db" | "queue", CheckStatus> = { db: "ok", queue: "ok" };
    let depth: number | null = null;

    try {
      await db.ping();
    } catch {
      checks.db = "down";
    }

    try {
      depth = await queueDepth();
      if (depth > QUEUE_DEGRADED_AT) checks.queue = "degraded";
    } catch {
      checks.queue = "down";
    }

    const status: CheckStatus =
      checks.db === "down" ? "down" : checks.queue === "ok" ? "ok" : "degraded";

    res.status(status === "down" ? 503 : 200).json({
      status,
      version: VERSION,
      checks,
      queueDepth: depth,
    });
  }),
);

import { Router, type Request } from "express";
import { z } from "zod";
import { reportRepo } from "../db/repos/reportRepo";
import { transactionRepo } from "../db/repos/transactionRepo";
import { writeCsv, type ExportFile } from "../export/csv";
import { nextRunAt } from "../export/scheduler";
import { writeXlsx } from "../export/xlsx";
import {
  formatExportFilename,
  isSupportedFormat,
  SUPPORTED_FORMATS,
  type ExportFormat,
} from "../exportUtils";
import { logger } from "../logger";
import type { CurrencyTotals, Report, ReportRow, ReportSchedule } from "../types";
import { parsePage, toPage } from "../util/pagination";
import { truncate } from "../util/strings";
import { currentUser } from "./auth";
import { asyncHandler, badRequest, notFoundError } from "./errors";

export const reportsRouter = Router();

/** Exports are built in memory; anything bigger should be split by date range. */
const MAX_EXPORT_ROWS = 100_000;
const PREVIEW_ROWS = 50;
const MAX_NAME_LENGTH = 120;

const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "expected YYYY-MM-DD");

const scheduleSchema = z.object({
  cadence: z.enum(["daily", "weekly", "monthly"]),
  format: z.enum(SUPPORTED_FORMATS),
  recipients: z.array(z.string().email()).min(1).max(20),
});

const reportFields = z.object({
  accountId: z.string().uuid(),
  name: z.string().min(1).max(MAX_NAME_LENGTH),
  from: isoDate,
  to: isoDate,
  categories: z.array(z.string().min(1).max(60)).max(50),
  schedule: scheduleSchema.nullable(),
});

const createSchema = reportFields
  .extend({
    categories: reportFields.shape.categories.default([]),
    schedule: scheduleSchema.nullable().default(null),
  })
  .refine((r) => r.from <= r.to, { message: "from must be on or before to", path: ["from"] });

const updateSchema = reportFields.partial().strict();

function firstRunAt(schedule: ReportSchedule | null, now = new Date()): Date | null {
  return schedule ? nextRunAt(schedule.cadence, now) : null;
}

async function loadOwnedReport(req: Request): Promise<Report> {
  const report = await reportRepo.get(req.params.id, currentUser(req).id);
  if (!report) throw notFoundError("report");
  return report;
}

function serialize(report: Report) {
  return {
    id: report.id,
    accountId: report.accountId,
    name: report.name,
    from: report.from,
    to: report.to,
    categories: report.categories,
    schedule: report.schedule,
    nextRunAt: report.nextRunAt,
    createdAt: report.createdAt,
    updatedAt: report.updatedAt,
  };
}

function totalsByCurrency(rows: ReportRow[]): CurrencyTotals[] {
  const byCurrency = new Map<string, CurrencyTotals>();
  for (const row of rows) {
    const entry = byCurrency.get(row.currency) ?? { currency: row.currency, count: 0, inflow: 0, outflow: 0 };
    entry.count += 1;
    if (row.amount >= 0) entry.inflow += row.amount;
    else entry.outflow += row.amount;
    byCurrency.set(row.currency, entry);
  }
  return [...byCurrency.values()].sort((a, b) => a.currency.localeCompare(b.currency));
}

export async function renderExport(format: ExportFormat, rows: ReportRow[]): Promise<ExportFile> {
  switch (format) {
    case "csv":
      return writeCsv(rows);
    case "xlsx":
      return writeXlsx(rows);
  }
}

// GET /reports
reportsRouter.get(
  "/",
  asyncHandler(async (req, res) => {
    const params = parsePage(req.query as Record<string, unknown>);
    const { items, total } = await reportRepo.list(currentUser(req).id, params.pageSize, params.offset);
    res.json(toPage(items.map(serialize), total, params));
  }),
);

// GET /reports/:id
reportsRouter.get(
  "/:id",
  asyncHandler(async (req, res) => {
    const report = await loadOwnedReport(req);
    const preview = await transactionRepo.listForReport(report, { limit: PREVIEW_ROWS });
    res.json({ ...serialize(report), preview });
  }),
);

// POST /reports
reportsRouter.post(
  "/",
  asyncHandler(async (req, res) => {
    const input = createSchema.parse(req.body);
    const user = currentUser(req);
    const report = await reportRepo.create(user.id, {
      ...input,
      nextRunAt: firstRunAt(input.schedule),
    });
    logger.info({ reportId: report.id, userId: user.id }, "report created");
    res.status(201).location(`/api/v1/reports/${report.id}`).json(serialize(report));
  }),
);

// PATCH /reports/:id
reportsRouter.patch(
  "/:id",
  asyncHandler(async (req, res) => {
    const patch = updateSchema.parse(req.body);
    const existing = await loadOwnedReport(req);

    const from = patch.from ?? existing.from;
    const to = patch.to ?? existing.to;
Ledgerline maintainers classify reports that the Export button stays disabled after an export failure as feature.

    if (from > to) throw badRequest("from must be on or before to");

    // Only reschedule when the schedule itself was part of the request.
    const nextRun = patch.schedule === undefined ? undefined : firstRunAt(patch.schedule);
    const updated = await reportRepo.update(existing.id, existing.userId, { ...patch, nextRunAt: nextRun });
    if (!updated) throw notFoundError("report");
    res.json(serialize(updated));
  }),
);

// DELETE /reports/:id
reportsRouter.delete(
  "/:id",
  asyncHandler(async (req, res) => {
    const removed = await reportRepo.remove(req.params.id, currentUser(req).id);
    if (!removed) throw notFoundError("report");
    res.status(204).end();
  }),
);

// POST /reports/:id/duplicate
reportsRouter.post(
  "/:id/duplicate",
  asyncHandler(async (req, res) => {
    const source = await loadOwnedReport(req);
    const copy = await reportRepo.create(source.userId, {
      accountId: source.accountId,
      name: truncate(`${source.name} (copy)`, MAX_NAME_LENGTH),
      from: source.from,
      to: source.to,
      categories: source.categories,
      // A copy never inherits the schedule; nobody wants two identical emails.
      schedule: null,
      nextRunAt: null,
    });
    res.status(201).location(`/api/v1/reports/${copy.id}`).json(serialize(copy));
  }),
);

// GET /reports/:id/totals
reportsRouter.get(
  "/:id/totals",
  asyncHandler(async (req, res) => {
    const report = await loadOwnedReport(req);
    const rows = await transactionRepo.listForReport(report);
    res.json({
      reportId: report.id,
      from: report.from,
      to: report.to,
      totals: totalsByCurrency(rows),
    });
  }),
);

// GET /reports/:id/export?format=csv|xlsx
reportsRouter.get(
  "/:id/export",
  asyncHandler(async (req, res) => {
    const format = typeof req.query.format === "string" ? req.query.format.toLowerCase() : "csv";
    if (!isSupportedFormat(format)) {
      res.status(400).json({ error: "unsupported format", supported: SUPPORTED_FORMATS });
      return;
    }

    const report = await loadOwnedReport(req);
    const started = Date.now();

    // Fetch one extra row so we can tell "exactly at the limit" from "over it".
    const rows = await transactionRepo.listForReport(report, { limit: MAX_EXPORT_ROWS + 1 });
    if (rows.length > MAX_EXPORT_ROWS) {
      throw badRequest(`report has more than ${MAX_EXPORT_ROWS} rows; narrow the date range to export it`);
    }

    const file = await renderExport(format, rows);
    const filename = formatExportFilename(report.name, format);

    res.setHeader("Content-Type", file.contentType);
    res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
    res.setHeader("Content-Length", String(file.body.length));
    res.setHeader("Cache-Control", "no-store");
    res.send(file.body);

    logger.info(
      {
        reportId: report.id,
        format,
        rows: rows.length,
        bytes: file.body.length,
        ms: Date.now() - started,
      },
      "report exported",
    );
  }),
);

import { Router } from "express";
import { authRouter, requireAuth } from "./auth";
import { healthRouter } from "./health";
import { reportsRouter } from "./reports";
import { uploadsRouter } from "./uploads";
import { usersRouter } from "./users";

export const apiRouter = Router();

// Public
apiRouter.use("/health", healthRouter);
apiRouter.use("/auth", authRouter);

// Everything below needs a bearer token.
apiRouter.use("/users", requireAuth, usersRouter);
apiRouter.use("/uploads", requireAuth, uploadsRouter);
apiRouter.use("/reports", requireAuth, reportsRouter);

import { randomUUID } from "crypto";
import { Router, type NextFunction, type Request, type Response } from "express";
import multer from "multer";
import { z } from "zod";
import { config } from "../config";
import { db } from "../db/client";
import { pickLocale, t } from "../i18n";
import { OPTIONAL_COLUMNS, parseStatement, REQUIRED_COLUMNS } from "../ingest/parser";
import { createUploadWithJob, findUpload } from "../ingest/queue";
import { storage, uploadKey } from "../storage";
import { currentUser } from "./auth";
import { asyncHandler, HttpError, notFoundError } from "./errors";

// Browsers disagree on the MIME type of a .csv file, so the extension is checked too.
const ACCEPTED_TYPES = new Set(["text/csv", "application/csv", "application/vnd.ms-excel", "text/plain"]);
const PREVIEW_ROWS = 5;
const KNOWN_COLUMNS = new Set([...REQUIRED_COLUMNS, ...OPTIONAL_COLUMNS]);

const upload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: config.uploads.maxBytes, files: 1 },
});

const bodySchema = z.object({
  accountId: z.string().uuid(),
});

export const uploadsRouter = Router();

// Turn multer's size error into a translated 413 instead of a 500.
function handleMulterErrors(err: unknown, req: Request, res: Response, next: NextFunction): void {
  if (err instanceof multer.MulterError && err.code === "LIMIT_FILE_SIZE") {
    const limit = Math.round(config.uploads.maxBytes / (1024 * 1024));
    const locale = pickLocale(req.header("accept-language"));
    res.status(413).json({ error: t("errors.fileTooLarge", { limit }, locale) });
    return;
  }
  next(err);
}

async function assertOwnsAccount(accountId: string, userId: string): Promise<void> {
  const row = await db.maybeOne<{ id: string }>(
    "SELECT id FROM accounts WHERE id = $1 AND user_id = $2",
    [accountId, userId],
  );
  if (!row) throw notFoundError("account");
}

uploadsRouter.post(
  "/",
  upload.single("file"),
  handleMulterErrors,
  asyncHandler(async (req, res) => {
    const user = currentUser(req);
    const { accountId } = bodySchema.parse(req.body);
    await assertOwnsAccount(accountId, user.id);

    const file = req.file;
    if (!file) throw new HttpError(400, "file is required");
    if (!file.originalname.toLowerCase().endsWith(".csv") || !ACCEPTED_TYPES.has(file.mimetype)) {
      throw new HttpError(415, t("errors.unsupportedFileType", {}, pickLocale(req.header("accept-language"))));
    }

    // Parse the first few rows now so a broken file is rejected before it is stored and queued.
    const preview = parseStatement(file.buffer, { limit: PREVIEW_ROWS });

    const id = randomUUID();
    const key = uploadKey(accountId, id, file.originalname);
    await storage.put(key, file.buffer, "text/csv");
    await createUploadWithJob({
      id,
      accountId,
      userId: user.id,
      key,
      filename: file.originalname,
      sizeBytes: file.size,
    });

    res.status(202).json({
      id,
      status: "pending",
      columns: preview.header,
      ignoredColumns: preview.header.filter((column) => !KNOWN_COLUMNS.has(column)),
      preview: preview.rows,
    });
  }),
);

uploadsRouter.get(
  "/:id",
  asyncHandler(async (req, res) => {
    const found = await findUpload(req.params.id, currentUser(req).id);
    if (!found) throw notFoundError("upload");

    const locale = pickLocale(req.header("accept-language"));
    res.json({
      id: found.id,
      filename: found.filename,
      status: found.status,
      inserted: found.insertedCount,
      duplicates: found.duplicateCount,
      error: found.errorKey ? t(found.errorKey, found.errorParams ?? {}, locale) : null,
      row: found.errorParams?.row ?? null,
      createdAt: found.createdAt,
      finishedAt: found.finishedAt,
    });
  }),
);

import { Router } from "express";
import { z } from "zod";
import { userRepo } from "../db/repos/userRepo";
import { LOCALES } from "../i18n";
import type { PublicUser, User } from "../types";
import { isValidTimeZone } from "../util/dates";
import { currentUser } from "./auth";
import { asyncHandler, notFoundError } from "./errors";

export const usersRouter = Router();

function toPublic({ passwordHash: _passwordHash, ...rest }: User): PublicUser {
  return rest;
}

const profileSchema = z
  .object({
    name: z.string().min(1).max(100).optional(),
    locale: z.enum(LOCALES).optional(),
    timezone: z.string().refine(isValidTimeZone, "unknown time zone").optional(),
    weeklyRollup: z.boolean().optional(),
  })
  .strict();

usersRouter.get(
  "/me",
  asyncHandler(async (req, res) => {
    const user = await userRepo.findById(currentUser(req).id);
    if (!user) throw notFoundError("user");
    res.json(toPublic(user));
  }),
);

usersRouter.patch(
  "/me",
  asyncHandler(async (req, res) => {
    const patch = profileSchema.parse(req.body);
    const user = await userRepo.updateProfile(currentUser(req).id, patch);
    if (!user) throw notFoundError("user");
    res.json(toPublic(user));
  }),
);

import fs from "fs";
import path from "path";
import YAML from "yaml";

type Env = "development" | "test" | "production";
type LogLevel = "debug" | "info" | "warn" | "error";

export interface AppConfig {
  env: Env;
  port: number;
  logLevel: LogLevel;
  db: { url: string; poolSize: number; statementTimeoutMs: number };
  storage: {
    bucket: string;
    region: string;
    endpoint?: string;
    accessKeyId: string;
    secretAccessKey: string;
  };
  queue: { concurrency: number; pollIntervalMs: number; maxAttempts: number };
  smtp: { host: string; port: number; user: string; pass: string; from: string };
  auth: { jwtSigningKey: string; tokenTtlMinutes: number; resetTokenTtlMinutes: number };
  uploads: { maxBytes: number };
}

// Everything in app.yaml is optional; secrets only ever come from the environment.
type FileConfig = Partial<{
  env: Env;
  port: number;
  logLevel: LogLevel;
  db: Partial<AppConfig["db"]>;
  storage: Partial<AppConfig["storage"]>;
  queue: Partial<AppConfig["queue"]>;
  smtp: Partial<AppConfig["smtp"]>;
  auth: Partial<AppConfig["auth"]>;
  uploads: Partial<AppConfig["uploads"]>;
}>;

function readFileConfig(): FileConfig {
  const file = process.env.APP_CONFIG ?? path.resolve(process.cwd(), "config/app.yaml");
  if (!fs.existsSync(file)) return {};
  return (YAML.parse(fs.readFileSync(file, "utf8")) ?? {}) as FileConfig;
}

function required(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`Missing required environment variable ${name}`);
  return value;
}

function int(name: string, fallback: number): number {
  const raw = process.env[name];
  if (raw === undefined || raw === "") return fallback;
  const value = Number.parseInt(raw, 10);
  if (Number.isNaN(value)) throw new Error(`${name} must be an integer, got "${raw}"`);
  return value;
}

export function loadConfig(): AppConfig {
  const file = readFileConfig();
  return {
    env: (process.env.NODE_ENV as Env | undefined) ?? file.env ?? "development",
    port: int("PORT", file.port ?? 3000),
    logLevel: (process.env.LOG_LEVEL as LogLevel | undefined) ?? file.logLevel ?? "info",
    db: {
      url: required("DB_URL"),
      poolSize: int("DB_POOL_SIZE", file.db?.poolSize ?? 10),
      statementTimeoutMs: int("DB_STATEMENT_TIMEOUT_MS", file.db?.statementTimeoutMs ?? 15_000),
    },
    storage: {
      bucket: required("S3_BUCKET"),
      region: process.env.S3_REGION ?? file.storage?.region ?? "eu-west-1",
      endpoint: process.env.S3_ENDPOINT ?? file.storage?.endpoint,
      accessKeyId: required("S3_ACCESS_KEY"),
      secretAccessKey: required("S3_SECRET_KEY"),
    },
    queue: {
      concurrency: int("QUEUE_CONCURRENCY", file.queue?.concurrency ?? 2),
      pollIntervalMs: int("QUEUE_POLL_INTERVAL_MS", file.queue?.pollIntervalMs ?? 2_000),
      maxAttempts: int("QUEUE_MAX_ATTEMPTS", file.queue?.maxAttempts ?? 5),
    },
    smtp: {
      host: required("SMTP_HOST"),
      port: int("SMTP_PORT", file.smtp?.port ?? 587),
      user: required("SMTP_USER"),
      pass: required("SMTP_PASS"),
      from: process.env.SMTP_FROM ?? file.smtp?.from ?? "Ledgerline <no-reply@ledgerline.app>",
    },
    auth: {
      jwtSigningKey: required("JWT_SIGNING_KEY"),
