import { createHash, randomBytes } from "crypto";
import bcrypt from "bcryptjs";
import { Router, type NextFunction, type Request, type Response } from "express";
import jwt from "jsonwebtoken";
import { z } from "zod";
import { config } from "../config";
import { userRepo } from "../db/repos/userRepo";
import { logger } from "../logger";
import { sendEmail } from "../notifications/email";
import { passwordResetEmail } from "../notifications/templates";
import type { AuthUser } from "../types";
import { addMinutes } from "../util/dates";
import { asyncHandler, HttpError } from "./errors";

declare global {
  // eslint-disable-next-line @typescript-eslint/no-namespace
  namespace Express {
    interface Request {
      user?: AuthUser;
    }
  }
}

const BCRYPT_ROUNDS = 12;

const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(1),
});

const resetRequestSchema = z.object({
  email: z.string().email(),
});

const resetConfirmSchema = z.object({
  token: z.string().min(32).max(128),
  password: z.string().min(10).max(200),
});

const sha256 = (value: string) => createHash("sha256").update(value).digest("hex");

export function issueToken(user: AuthUser): string {
  return jwt.sign({ sub: user.id, email: user.email }, config.auth.jwtSigningKey, {
    expiresIn: `${config.auth.tokenTtlMinutes}m`,
  });
}

export function requireAuth(req: Request, _res: Response, next: NextFunction): void {
  const [scheme, token] = (req.header("authorization") ?? "").split(" ");
  if (scheme !== "Bearer" || !token) {
    next(new HttpError(401, "authentication required"));
    return;
  }
  try {
    const payload = jwt.verify(token, config.auth.jwtSigningKey) as jwt.JwtPayload;
    req.user = { id: String(payload.sub), email: String(payload.email) };
    next();
  } catch {
    next(new HttpError(401, "invalid or expired token"));
  }
}

export function currentUser(req: Request): AuthUser {
  if (!req.user) throw new HttpError(401, "authentication required");
  return req.user;
}

export const authRouter = Router();

authRouter.post(
  "/login",
  asyncHandler(async (req, res) => {
    const { email, password } = loginSchema.parse(req.body);
    const user = await userRepo.findByEmail(email);
    const ok = user ? await bcrypt.compare(password, user.passwordHash) : false;
    if (!user || !ok) throw new HttpError(401, "invalid email or password");
    res.json({ token: issueToken(user), expiresInMinutes: config.auth.tokenTtlMinutes });
  }),
);

authRouter.post(
  "/password-reset",
  asyncHandler(async (req, res) => {
    const { email } = resetRequestSchema.parse(req.body);
    const user = await userRepo.findByEmail(email);
    if (user) {
      const token = randomBytes(32).toString("hex");
      const expiresAt = addMinutes(new Date(), config.auth.resetTokenTtlMinutes);
      // Only the hash is stored; the raw token exists in the email and nowhere else.
      await userRepo.createResetToken(user.id, sha256(token), expiresAt);
      await sendEmail(passwordResetEmail(user, token));
      logger.info({ userId: user.id }, "password reset requested");
    }
    // Same response whether or not the account exists.
    res.status(202).json({ ok: true });
  }),
);

authRouter.post(
  "/password-reset/confirm",
  asyncHandler(async (req, res) => {
    const { token, password } = resetConfirmSchema.parse(req.body);
    const userId = await userRepo.consumeResetToken(sha256(token));
    if (!userId) throw new HttpError(400, "reset link is invalid or has expired");
    await userRepo.setPassword(userId, await bcrypt.hash(password, BCRYPT_ROUNDS));
    logger.info({ userId }, "password reset completed");
    res.status(204).end();
  }),
);

import type { NextFunction, Request, RequestHandler, Response } from "express";
import { ZodError } from "zod";
import { pickLocale, t } from "../i18n";
import { isIngestError } from "../ingest/errors";
import { logger } from "../logger";

export class HttpError extends Error {
  constructor(
    readonly status: number,
    message: string,
    readonly details?: unknown,
  ) {
    super(message);
    this.name = "HttpError";
  }
}

export const badRequest = (message: string, details?: unknown) => new HttpError(400, message, details);
export const notFoundError = (what: string) => new HttpError(404, `${what} not found`);

type AsyncRoute = (req: Request, res: Response) => Promise<unknown>;

/** Express 4 does not forward rejected promises to error middleware, so wrap async handlers. */
export const asyncHandler =
  (fn: AsyncRoute): RequestHandler =>
  (req, res, next) => {
    fn(req, res).catch(next);
  };

export function notFound(_req: Request, res: Response): void {
  res.status(404).json({ error: "not found" });
}

// Express recognises error middleware by its four parameters, so keep `_next`.
export function errorHandler(err: unknown, req: Request, res: Response, _next: NextFunction): void {
  if (res.headersSent) {
    logger.warn({ err, requestId: res.locals.requestId }, "error after response started");
    res.end();
    return;
  }

  if (err instanceof HttpError) {
    res.status(err.status).json({ error: err.message, details: err.details });
    return;
  }

  if (err instanceof ZodError) {
    res.status(400).json({ error: "validation failed", details: err.flatten().fieldErrors });
    return;
  }

  if (isIngestError(err)) {
    // Upload content problems: translate for the caller and pass the row number through.
    const locale = pickLocale(req.header("accept-language"));
    res.status(422).json({
      error: t(err.key, err.params, locale),
      code: err.key,
      row: err.params.row ?? null,
    });
    return;
  }

  logger.error({ err, requestId: res.locals.requestId }, "unhandled error");
  res.status(500).json({ error: "internal error", requestId: res.locals.requestId });
}

import { Router } from "express";
import { db } from "../db/client";
import { queueDepth } from "../ingest/queue";
import { asyncHandler } from "./errors";

type CheckStatus = "ok" | "degraded" | "down";

/** Above this many runnable import jobs we report the queue as degraded. */
const QUEUE_DEGRADED_AT = 500;
const VERSION = process.env.npm_package_version ?? "dev";

export const healthRouter = Router();

// Liveness: the process is up and the event loop is responsive.
healthRouter.get("/live", (_req, res) => {
  res.json({ status: "ok" });
});

// Readiness: dependencies are reachable.
healthRouter.get(
  "/",
  asyncHandler(async (_req, res) => {
    const checks: Record<"db" | "queue", CheckStatus> = { db: "ok", queue: "ok" };
    let depth: number | null = null;

    try {
      await db.ping();
    } catch {
      checks.db = "down";
    }

    try {
      depth = await queueDepth();
      if (depth > QUEUE_DEGRADED_AT) checks.queue = "degraded";
    } catch {
      checks.queue = "down";
    }

    const status: CheckStatus =
      checks.db === "down" ? "down" : checks.queue === "ok" ? "ok" : "degraded";

    res.status(status === "down" ? 503 : 200).json({
      status,
      version: VERSION,
      checks,
      queueDepth: depth,
    });
  }),
);

import { Router, type Request } from "express";
