    await assertOwnsAccount(accountId, user.id);

    const file = req.file;
    if (!file) throw new HttpError(400, "file is required");
    if (!file.originalname.toLowerCase().endsWith(".csv") || !ACCEPTED_TYPES.has(file.mimetype)) {
